def parse_offset_aware(s):
    """Parse an offset-aware ISO8601 datetime string to a timezone-aware datetime."""
    if s is None:
        return None
    # Handle 'Z' suffix
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    # Python 3.7+ fromisoformat handles offset strings
    dt = datetime.fromisoformat(s)
    # Must be offset-aware (have tzinfo)
    if dt.tzinfo is None:
        return None  # naive → skip
    return dt


def format_utc(dt):
    """Format a timezone-aware datetime as YYYY-MM-DDTHH:MM:SSZ in UTC."""
    utc_dt = dt.astimezone(timezone.utc)
    return utc_dt.strftime('%Y-%m-%dT%H:%M:%SZ')


