import json
import sys
from datetime import datetime, timezone, timedelta


def parse_offset_aware(s):
    """Parse an offset-aware ISO8601 datetime string to a timezone-aware datetime."""
    if s is None:
        return None
    # Handle 'Z' suffix
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    # Python 3.7+ fromisoformat handles offset strings
    dt = datetime.fromisoformat(s)
    # Must be offset-aware (have tzinfo)
    if dt.tzinfo is None:
        return None  # naive → skip
    return dt


def format_utc(dt):
    """Format a timezone-aware datetime as YYYY-MM-DDTHH:MM:SSZ in UTC."""
    utc_dt = dt.astimezone(timezone.utc)
    return utc_dt.strftime('%Y-%m-%dT%H:%M:%SZ')


def main():
    with open(sys.argv[1]) as f:
        data = json.load(f)

    as_of = parse_offset_aware(data['as_of'])
    if as_of is None:
        print(json.dumps([]))
        return

    results = []
    for r in data.get('reminders', []):
        # Skip completed reminders
        if r.get('completed', False):
            continue

        # Parse due value; skip if missing, null, or naive
        due_raw = r.get('due')
        due = parse_offset_aware(due_raw)
        if due is None:
            continue

        # Include only if due AT OR BEFORE as_of
        if due <= as_of:
            results.append({
                'id': r['id'],
                'title': r['title'],
                'due_utc': format_utc(due)
            })

    # Sort by actual due instant (ascending), then by id (ascending)
    results.sort(key=lambda x: (parse_offset_aware(x['due_utc']), x['id']))

    print(json.dumps(results))


if __name__ == '__main__':
    main()
